        .first { table[$0] != nil } ?? "en"

    static func text(_ key: String, _ vars: [String: String] = [:]) -> String {
        text(key, vars, lang: language)
    }

    /// The same, in a given language (tests pin one).
    static func text(_ key: String, _ vars: [String: String] = [:], lang: String) -> String {
